function moduleHelp(type){
 if(type.startsWith('store-')&&type!=='store-search')return '<p class="module-help muted">Uses your local data store. Record fields must match its data structure. Map returned data with <code>{{record.fieldName}}</code>, <code>{{key}}</code>, <code>{{exists}}</code> or <code>{{count}}</code>. Successful writes remain saved if a later module fails.</p>';
 const help={
  'json-create':'Enter JSON with mapped values, such as {"name":"{{data.name}}","count":"{{data.count}}"}. Exact mappings preserve numbers, booleans, objects and arrays. Leave empty to serialize the current bundle. This local form uses JSON input rather than a data-structure builder.',
  'json-parse':'Split produces one output bundle per array item; access it as {{data}} or {{data.field}}. Single keeps the entire array in {{data}} for use with Iterator. Existing modules without a saved option keep the single behavior.',
  'json-aggregate':'Combines all current incoming bundles into one JSON array string. Leave the mapped value empty to include each full bundle, or enter {{data}} or {{record}} to select its value. No grouping is applied.',
  'store-search':'Optionally select a top-level record field and a comparison. Use Exists or Does not exist without a comparison value. Date comparisons follow the filter date formats. Results are ordered by record key, with at most 100 results.',
  'set-variables':'Enter a JSON object, for example {"name":"Ada","score":42}. Values can map earlier fields, such as {"score":"{{value}}"}. All values are evaluated before setting the variables.',
  'get-variable':'Read a variable from the current bundle. Its original type is preserved in the value output.',
  'get-variables':'Read selected variables from the current bundle. Map a result with {{variables.name}}.',
  'increment':'Returns 1 on the first execution, then increases by 1 each time this module runs. The counter is saved with this scenario, including across restarts. Cloned scenarios start their own counters.',
  'basic-trigger':'Place this module first. Each object becomes a separate bundle, for example [{"name":"Ada"},{"name":"Lin"}]. Up to 100 bundles can be generated.',
  'switch':'Enter cases such as [{"match":"yes","output":"Approved"}]. The first exact match is used; otherwise the fallback is used. Map the result with {{output}}.',
  'text-aggregator':'Combines text from all incoming bundles into one text output. Enter a literal separator; press Enter for a new line.',
  'numeric-aggregator':'Aggregates values from all incoming bundles into one result. Map the result with {{result}}. Count counts the bundles and does not require a value.'
 };
 return help[type]?`<p class="module-help muted">${esc(help[type])}</p>`:'';
}
function configureFilter(id){
 const module=scenario.graph.find(m=>m.id===id);
 const operators=['Equal to','Not equal to','Contains','Does not contain','Starts with','Ends with','Greater than','Greater than or equal to','Less than','Less than or equal to','Exists','Does not exist','Array contains','Array does not contain','Datetime equal to','Datetime not equal to','Later than','Later than or equal to','Earlier than','Earlier than or equal to'];
 let conditions=structuredClone(module.config.conditions||[{left:module.config.left||'',operator:module.config.operator||'Equal to',right:module.config.right||''}]);
 modal('Set up a filter',`<form id="module-form" class="config-form"><label for="filter-label">Label</label><input id="filter-label" value="${esc(module.config.label||'')}" maxlength="120"><label for="filter-match">Match</label><select id="filter-match"><option value="all" ${module.config.match!=='any'?'selected':''}>All conditions (AND)</option><option value="any" ${module.config.match==='any'?'selected':''}>Any condition (OR)</option></select><div id="filter-conditions"></div><button type="button" id="filter-add">+ Add condition</button><p class="muted">Map earlier values with <code>{{variableName}}</code>. Text comparisons are case-sensitive. Exists also accepts zero and false; missing, empty text and null are treated as absent.</p><p class="muted">Date comparisons accept ISO dates (2026-10-14), ISO timestamps with an offset or Z, or times such as 17:00 and 5PM. Dates without an offset use UTC. Compare two dates or two times.</p><div class="form-actions"><button type="button" class="danger" data-action="delete-module" data-id="${id}">Delete filter</button><button type="button" data-action="close">Cancel</button><button class="primary">Save</button></div></form>`);
 function read(){conditions=$$('.filter-condition').map(row=>({left:row.querySelector('[data-field="left"]').value,operator:row.querySelector('[data-field="operator"]').value,right:row.querySelector('[data-field="right"]').value}));}
 function show(){
  $('#filter-conditions').innerHTML=conditions.map((c,i)=>`<fieldset class="filter-condition"><legend>Condition ${i+1}</legend><label for="filter-left-${i}">Left operand</label><input id="filter-left-${i}" data-field="left" value="${esc(c.left)}"><label for="filter-operator-${i}">Operator</label><select id="filter-operator-${i}" data-field="operator">${operators.map(o=>`<option ${o===c.operator?'selected':''}>${o}</option>`).join('')}</select><div class="filter-right" ${['Exists','Does not exist'].includes(c.operator)?'hidden':''}><label for="filter-right-${i}">Right operand</label><input id="filter-right-${i}" data-field="right" value="${esc(c.right)}"></div><button type="button" class="ghost filter-remove" data-index="${i}" aria-label="Remove condition ${i+1}" ${conditions.length===1?'disabled':''}>Remove</button></fieldset>`).join('');
  $$('.filter-condition select').forEach(select=>select.onchange=()=>{select.closest('.filter-condition').querySelector('.filter-right').hidden=['Exists','Does not exist'].includes(select.value);});
  $$('.filter-remove').forEach(button=>button.onclick=()=>{read();conditions.splice(Number(button.dataset.index),1);show();});
  $('#filter-add').disabled=conditions.length>=20;
 }
 $('#filter-add').onclick=()=>{read();conditions.push({left:'',operator:'Equal to',right:''});show();};
 $('#module-form').onsubmit=e=>{e.preventDefault();read();snapshot();module.config={label:$('#filter-label').value,match:$('#filter-match').value,conditions};close();drawEditor();};show();
}
async function configure(id){if(scenario.graph.find(x=>x.id===id)?.type==='json-create')return configureJSONCreate(id);if(scenario.graph.find(x=>x.id===id)?.type==='filter')return configureFilter(id);let m=scenario.graph.find(x=>x.id===id),def=mods.find(d=>d.type===m.type);const stores=m.type.startsWith('store-')?await api('/resources/data-stores'):[];modal(def.app+' — '+def.name,`<form id="module-form" class="config-form">${def.fields.map(([key,label,type,options])=>`<label for="field-${key}">${label}</label>${type==='store'?`<select id="field-${key}" name="${key}" required><option value="">Select a data store</option>${m.config[key]&&!stores.some(s=>s.id===m.config[key])?`<option selected value="${esc(m.config[key])}">Unavailable data store</option>`:''}${stores.map(s=>`<option value="${s.id}" ${m.config[key]===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>${stores.length?'':'<p class="muted">Create a data store from Data stores before running this module.</p>'}`:type==='limit'?`<input id="field-${key}" name="${key}" type="number" min="1" max="100" step="1" required value="${esc(m.config[key]??100)}">`:type==='textarea'?`<textarea id="field-${key}" name="${key}">${esc(typeof m.config[key]==='object'?JSON.stringify(m.config[key],null,2):m.config[key]??(key==='separator'?'\n':''))}</textarea>`:type==='select'?`<select id="field-${key}" name="${key}">${options.map(o=>`<option ${(m.config[key]??(m.type==='json-parse'&&key==='array_mode'?'single':undefined))===o?'selected':''}>${o}</option>`).join('')}</select>`:`<input id="field-${key}" name="${key}" type="${type||'text'}" value="${esc(m.config[key]??'')}" ${type==='number'?'min="0" max="2" step="0.1"':''}>`}`).join('')}${moduleHelp(m.type)}${m.type==='webhook'?`<p><button type="button" data-action="setup-webhook" data-id="${m.id}">Set up webhook</button></p>`:''}<p class="muted">Map a previous value using <code>{{variableName}}</code>.</p><div class="form-actions"><button type="button" class="danger" data-action="delete-module" data-id="${id}">Delete module</button><button type="button" data-action="close">Cancel</button><button class="primary">Save</button></div></form>`);$('#module-form').onsubmit=e=>{e.preventDefault();snapshot();m.config=Object.fromEntries(new FormData(e.target));close();drawEditor();};}
async function saveScenario(){scenario.name=$('#scenario-name')?.value||scenario.name;const saved=await api('/scenarios'+(scenario.id?'/'+scenario.id:''),scenario.id?'PUT':'POST',scenario);scenario=saved;dirty=false;history.replaceState({},'','/1/scenarios/'+saved.id+'/edit');drawEditor();return saved;}
function showRun(run){modal('Execution '+(run.status==='success'?'completed':'failed'),`<p>${new Date(run.started*1000).toLocaleString()} · ${run.operations} operations · ${run.duration}s · ${(run.output||[]).length} output bundles</p>${run.steps.map((s,i)=>`<details class="run-step" open><summary class="${s.status==='success'?'success':''}">${i+1}. ${esc(mods.find(m=>m.type===s.type)?.name||s.type)} — ${esc(s.status)}</summary>${s.error?`<p class="error">${esc(s.error)}</p>`:`<small>Input</small><pre>${esc(JSON.stringify(s.input,null,2))}</pre><small>Output</small><pre>${esc(JSON.stringify(s.output,null,2))}</pre>`}</details>`).join('')}`,true);}
async function historyModal(id){id=id||scenario?.id;if(!id)return toast('Save your scenario to view its history.');const runs=await api('/scenarios/'+id+'/runs');modal('Scenario history',runs.length?runs.map((r,i)=>`<button class="module-option" data-run-index="${i}"><span class="${r.status==='success'?'success':''}">${r.status==='success'?'✓':'!'}</span><span>${new Date(r.started*1000).toLocaleString()}<small>${r.status} · ${esc(r.trigger||'manual')} · ${r.operations} operations · ${r.duration}s</small></span></button>`).join(''):'<p>No executions yet. Run your scenario to see the results here.</p>',true);$$('[data-run-index]').forEach(e=>e.onclick=()=>showRun(runs[Number(e.dataset.runIndex)]));}
async function resourcePage(kind){const info={'data-stores':['Data stores','Add data store',"You haven't added any data stores yet"],devices:['Devices','Add device',"You haven't added any devices yet"],udts:['Data structures','Add data structure',"You haven't created any data structures yet"],hooks:['Webhooks','Add webhook',"You haven't created any webhooks yet"],keys:['Keys','Add key',"You haven't created any keys yet"],connections:['Connections','Add connection','All connections'],'agent-profiles':['MCP Toolboxes','Create toolbox','No toolboxes yet'],apps:['Custom Apps','Create app','Create your first custom app']}[kind];const rows=await api('/resources/'+kind);shell(`<div class="flex between"><h1>${info[0]}</h1>${info[1]?`<button class="primary" data-action="resource-add" data-kind="${kind}">${info[1]}</button>`:''}</div>${kind==='connections'?'<p>All connections</p>':''}${rows.length?`<table class="table"><thead><tr><th>Name</th><th>Created</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${new Date(r.created*1000).toLocaleString()}</td><td><button data-action="resource-view" data-id="${r.id}" data-kind="${kind}">View</button> <button data-action="resource-delete" data-id="${r.id}" data-kind="${kind}">Delete</button></td></tr>`).join('')}</tbody></table>`:`<section class="empty"><h3>${info[2]}</h3>${kind==='agent-profiles'?'<p>MCP Toolboxes let AI clients like Claude and ChatGPT run your Make scenarios as tools, with full control over what you share and with whom.</p>':kind==='apps'?'<p>Think of a custom app as a translator between Make and a third-party API. It defines how to connect and authenticate, and how to interpret the API’s responses.</p>':''}</section>`}`,['connections','keys'].includes(kind)?'credentials':'',`resource-page ${['data-stores','devices','udts','hooks','keys'].includes(kind)?'compact-resource':''}`);if(kind==='hooks'&&new URLSearchParams(location.search).has('scenario')){await resourceAdd('hooks');history.replaceState({},'','/1/hooks');}}
async function resourceAdd(kind,onCreated=null){
 const titles={hooks:'Add webhook','folders':'Add folder','labels':'Create label','data-stores':'Add data store',udts:'Add data structure',devices:'Add device','agent-profiles':'Create toolbox',connections:'Add connection',keys:'Add key',apps:'Create app'};
 const structures=kind==='data-stores'?await api('/resources/udts'):[];
 const availableScenarios=['agent-profiles','hooks'].includes(kind)?await api('/scenarios'):[];
 const scenarios=availableScenarios.filter(s=>kind==='hooks'?s.graph[0]?.type==='webhook':s.active&&s.interval_minutes===0);
 let fields=kind==='devices'?'<p>To get started, you’ll need the Make app on your phone. Enter a name for this device and tap Continue.</p>':'';
 fields+=`<label for="resource-name">${({'data-stores':'Data store name',udts:'Data structure name',devices:'Device name'})[kind]||'Name'}*</label><input id="resource-name" name="name" required maxlength="160">`;
 if(kind==='data-stores')fields+=`<label for="structure-select">Data structure</label><select id="structure-select" name="structure"><option value="">Select a data structure</option>${structures.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select><p><a href="/1/udts">Create a data structure</a></p><small>If you don’t select a data structure, the database will only contain the primary key. Such database type is useful if you only want to save keys and are only interested in knowing whether or not a specific key exists in the database.</small><label for="storage-size">Data storage size in MB*</label><input id="storage-size" name="size" type="number" min="1" max="1" value="1" required><small>Must be equal to 1.</small>`;
 if(kind==='udts')fields+=`<label>Specification*</label><div class="flex"><button type="button" id="schema-add-item">Add item</button><button type="button" id="schema-generate">Generate</button></div><div id="schema-items"></div><textarea id="resource-config" name="schema" aria-label="Data structure specification">{"type":"object","properties":{}}</textarea><label>Strict</label><div class="flex"><label><input name="strict" type="radio" value="yes"> Yes</label><label><input name="strict" type="radio" value="no" checked> No</label></div><small>If checked, this data structure will be compared to the structure of the payload and if the payload contains extra items not specified in the data structure, the payload will be rejected.</small>`;
 if(kind==='hooks')fields+=`<label for="hook-scenario">Scenario</label><select id="hook-scenario" name="scenario" required>${scenarios.map(s=>`<option value="${s.id}" ${new URLSearchParams(location.search).get('scenario')===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><p class="muted">Choose a saved scenario whose first module is a Custom webhook. Requests wait in the queue while the scenario is inactive.</p><a href="/1/scenarios/add">Create scenario</a>`;
 if(kind==='agent-profiles')fields+=`<label>Scenarios</label>${scenarios.length?scenarios.map(s=>`<label><input type="checkbox" name="scenarios" value="${s.id}"> ${esc(s.name)}</label>`).join(''):'<p>No scenarios found</p>'}<a href="/1/scenarios/add">Create scenario</a><p>Tools are the scenarios available to your MCP client. Only active scenarios with on-demand scheduling can be used as tools.</p>`;
 modal(titles[kind],`<form id="resource-form" class="config-form">${fields}<div class="form-actions"><button type="button" data-action="close">Close</button><button class="primary">${kind==='devices'?'Continue':kind==='agent-profiles'?'Create':'Save'}</button></div></form>`);
 if(kind==='udts'){
  $('#schema-add-item').onclick=()=>{const row=document.createElement('div');row.className='flex';row.style.margin='12px 0';row.innerHTML='<input placeholder="Name" aria-label="Field name"><select aria-label="Field type"><option>string</option><option>number</option><option>boolean</option><option>object</option><option>array</option></select><button type="button" aria-label="Remove item">×</button>';row.querySelector('button').onclick=()=>row.remove();$('#schema-items').append(row);};
  $('#schema-generate').onclick=()=>{const sample=prompt('Paste a sample JSON object to generate the data structure');if(sample===null)return;try{const value=JSON.parse(sample);if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Enter a JSON object');$('#resource-config').value=JSON.stringify({type:'object',properties:Object.fromEntries(Object.entries(value).map(([k,v])=>[k,{type:Array.isArray(v)?'array':typeof v==='object'?'object':typeof v==='number'?'number':typeof v==='boolean'?'boolean':'string'}]))},null,2);}catch(e){toast(e.message);}};
 }
 $('#resource-form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);let config={};if(kind==='data-stores'){const structure=structures.find(x=>x.id===f.get('structure'));config={maxSizeMB:Number(f.get('size')),schema:structure?.config.schema||{type:'object',properties:{}},strict:structure?!!structure.config.strict:true};}if(kind==='udts'){const schema=JSON.parse(f.get('schema'));schema.properties=schema.properties||{};$$('#schema-items .flex').forEach(row=>{const name=row.querySelector('input').value.trim();if(!name)throw Error('Field name is required');schema.properties[name]={type:row.querySelector('select').value};});config={schema,strict:f.get('strict')==='yes'};}if(kind==='agent-profiles')config={scenarios:f.getAll('scenarios')};if(kind==='hooks')config={scenario:f.get('scenario')};if(kind==='devices')config={status:'awaiting-pairing'};const created=await api('/resources/'+kind,'POST',{name:f.get('name'),config});close();if(onCreated){await onCreated(created);return;}if(['hooks','agent-profiles'].includes(kind)){go('/1/'+kind+'/'+created.id);return;}await render();toast('Saved');}catch(err){toast(err.message);}};
}
