 if(mode==='resend'&&pendingAuth?.email)$('#email').value=pendingAuth.email;
 const incomingCode=new URLSearchParams(location.hash.slice(1)).get('code');if(incomingCode&&$('#code')){$('#code').value=incomingCode;history.replaceState({},'',location.pathname);}
 if($('#password')){const input=$('#password'),wrap=document.createElement('div');wrap.className='password-field';input.before(wrap);wrap.append(input);const toggle=document.createElement('button');toggle.type='button';toggle.className='password-toggle';toggle.setAttribute('aria-label','Show password');toggle.setAttribute('aria-pressed','false');toggle.innerHTML=icon('eyeSlash');toggle.onclick=()=>{const visible=input.type==='password';input.type=visible?'text':'password';toggle.setAttribute('aria-label',visible?'Hide password':'Show password');toggle.setAttribute('aria-pressed',String(visible));toggle.innerHTML=icon(visible?'eye':'eyeSlash');};wrap.append(toggle);}
