async function templatePage(id){if(id){const t=templates.find(t=>t.path.split('/').pop()===id);if(!t)return shell('<h1>Template not found</h1>','templates');shell(`<article class="template-detail" ${t.detail?'':'data-boundary-page'}><a href="/templates">← Public templates</a><h1>${esc(t.title)}</h1><div class="template-visual">${(t.icon_meta||[]).map(i=>`<span class="detail-app-icon" style="background:${esc(i.color)}">${img(i.path)}</span>`).join('<span class="connector"></span>')}</div><div class="template-description">${t.detail?`<p>${esc(t.description)}</p><p>This is a predefined template that will make the creation of your scenario much easier. Of course, you can always expand and customize the scenario to meet your own individual needs.</p><button class="primary" data-action="template-use" data-id="${esc(id)}">Create new scenario from template</button>`:`<p>This template is listed in Public templates. Its detail page is outside the first five template details included in this local copy.</p><a href="/templates">Return to Public templates</a>`}</div></article>`);return;}
 shell(`<div class="templates-heading"><h1>Public templates</h1><div class="template-controls"><input id="template-search" placeholder="Search by apps or name" aria-label="Search templates"><a class="primary" href="/1/templates/add">+ New template</a></div></div><div class="templates-grid" id="templates"></div>`,'templates','templates-page');
 const show=()=>{const query=$('#template-search').value.trim().toLowerCase();const found=templates.filter(t=>(t.title+' '+(t.icon_meta||[]).map(i=>i.name).join(' ')).toLowerCase().includes(query));$('#templates').innerHTML=found.map(t=>`<div class="template-tile"><a class="template-card" href="${t.path}" aria-label="${esc(t.title)}"><div class="template-compact"><div class="app-icons">${(t.icon_meta||[]).map(i=>`<span class="template-app-icon" style="background:${esc(i.color)}">${img(i.path)}</span>`).join('')}${t.extra?`<span class="template-extra">${esc(t.extra)}</span>`:''}</div><h3>${esc(t.title)}</h3><small>Used ${t.uses} times</small></div>${t.preview?`<div class="template-preview"><img src="${esc(t.preview)}" alt="${esc(t.title)} workflow"><h3>${esc(t.title)}</h3><p>${esc(t.summary||t.description||'')}</p></div>`:''}</a></div>`).join('')||'<p class="templates-empty muted">No templates found</p>';};show();$('#template-search').addEventListener('input',show);
}
async function organization(page){if(page==='users')user=(await api('/session')).account;const title=page==='variables'?'Org Variables':orgNav.find(x=>x[1]===page)?.[0]||'Organization';let body='';const usage=['credit-usage','teams','users'].includes(page)?await api('/usage'):null;if(page==='teams')body=`<a class="team-list-row" href="/1/team"><span class="team-list-icon">${icon('users')}</span><strong>${esc(settings.team)}</strong><span class="team-usage">${usage.operations} credits used</span><span aria-hidden="true">›</span></a>`;
 else if(page==='users')body=`<div class="organization-table-wrap"><table class="table users-table"><thead><tr><th>User</th><th>Last login</th><th>Role</th><th>Teams</th><th>Private space</th></tr></thead><tbody><tr><td><div class="user-cell"><span class="user-avatar">${esc((user.display_name||'M').slice(0,2).toUpperCase())}</span><span><strong>${esc(user.display_name)}</strong><small>${esc(user.email_normalized)} | ID: ${esc(user.account_id)}</small></span></div></td><td>${user.last_login?`<time datetime="${new Date(user.last_login*1000).toISOString()}" title="${esc(new Date(user.last_login*1000).toLocaleString())}">${esc(new Date(user.last_login*1000).toLocaleString())}</time>`:'<span title="Last login time has not been recorded">—</span>'}</td><td><span class="role-label">Owner</span></td><td><a class="team-label" href="/1/team">${icon('users')} ${esc(settings.team)}</a></td><td>${usage.operations} credits used</td></tr></tbody></table><div class="table-pagination"><span>Items per page: <span class="page-size">50</span></span><span class="pagination-controls"><button disabled aria-label="Previous page">‹</button><span class="page-current" aria-current="page">1</span><button disabled aria-label="Next page">›</button></span><span>1 – 1 of 1</span></div></div>`;
 else if(page==='user-roles'){const roles=await fetch('/static/roles.json').then(r=>r.json());body=`<p class="roles-intro">Organization roles control access across your whole organization, including billing, users, and settings. Team roles control access within a single team, including scenarios and data. Each user has one organization role and a role in every team they belong to.</p><div class="role-list">${['11','12','13','14','15','16'].map(id=>{const r=roles[id];return `<div class="role-list-row"><div><strong>${esc(r.name)}</strong> <span class="pill">Default</span><p>${esc(r.description)}</p></div><a class="role-view" href="/organization/1/user-roles/organization/${id}">View</a></div>`;}).join('')}</div>`;}
 else if(page==='notification-options')body=[['warnings','Warning in scenario run','Notifications for warnings that need your attention, such as a data store in your scenario reaching capacity.'],['errors','Errors in scenario run','Notifications for errors that stop your scenarios from running smoothly, such as an app receiving a connection error.'],['deactivation','Scenario deactivation','Notifications for scenarios that are deactivated due to critical issues, such as multiple consecutive errors.'],['credits','Credit limit reached','Notifications when this team has reached its credit limit and all scenarios have been automatically paused.'],['connections','Connection and key activity','Notifications when someone else uses a connection or key you created. If turned off, this disables notifications for your individual connections and keys.']].map(([key,n,description])=>`<div class="panel flex between"><span><strong>${n}</strong><p class="muted">${description}</p></span><input type="checkbox" class="notification-check" data-preference="${key}" aria-label="${n}" ${(settings.notification_options?.[key]??settings.notifications)!==false?'checked':''}></div>`).join('');
 else if(page==='subscription')body=`<div class="panel"><h3>Current plan &nbsp; Free</h3><p>1,000 credits / month · $0.00 billed monthly</p></div><h2>Compare Plans</h2><div class="plans">${[['Free','0'],['Core','9.00'],['Pro','16.00'],['Teams','29.00']].map(([n,v])=>`<article class="plan"><h3>${n}</h3><h2>$${v}</h2><p>${n==='Free'?'Free forever':'/ month · Billed yearly'}</p><ul><li>${n==='Free'?'1,000':'10,000'} credits available monthly</li><li>${n==='Free'?'2 active':'Unlimited active'} scenarios</li><li>${n==='Free'?'15-minute':'1-minute'} minimum scheduling interval</li></ul><button data-action="plan" data-name="${n}" ${n==='Free'?'disabled':''}>${n==='Free'?'Current plan':'Get '+n}</button></article>`).join('')}</div>`;
 else if(page==='variables')return variablesPage();
 else if(page==='credit-usage')body=`<div class="settings-grid">${['Scenarios','Maia','Agents'].map(n=>`<div class="panel"><h3>${n}</h3><h1>${n==='Scenarios'?usage.operations:0} <small>credits</small></h1></div>`).join('')}</div><section class="empty">No items found</section>`;
 else if(['audit-logs','scenario-properties','event-subscriptions'].includes(page))body=`<section class="empty"><span class="badge">${page==='event-subscriptions'?'Teams':'Enterprise'}</span><h2>${page==='audit-logs'?'Unlock audit logs with Enterprise plan':page==='event-subscriptions'?'Deliver Make events wherever you need them':'Custom scenario properties'}</h2><p>${page==='scenario-properties'?'Keep your long list of scenarios organized. Learn more about custom scenario properties available on the Enterprise plan.':'Upgrade your plan to unlock this feature.'}</p><a href="/organization/1/subscription">Upgrade plan</a></section>`;
 else body=`<section class="empty">${page==='installed-apps'?'No apps were installed in this organization.':'No items found'}</section>`;
 if(page==='variables')body='<div class="organization-table-wrap">'+body+'<div class="table-pagination"><span>Items per page: <span class="page-size">25</span></span><span class="pagination-controls"><button disabled aria-label="Previous page">‹</button><span class="page-current" aria-current="page">1</span><button disabled aria-label="Next page">›</button></span><span>1 – 5 of 5</span></div></div>';
 shell(`<h1>${title}</h1>${page==='notification-options'?'<div class="notification-list">'+body+'</div>':body}`,'org','organization-page organization-'+page);$$('.notification-check').forEach(e=>e.onchange=async()=>{const checked=e.checked;e.disabled=true;try{settings=await api('/settings','PUT',{notification_options:{[e.dataset.preference]:checked}});toast('Notification options saved');}catch(err){e.checked=!checked;toast(err.message);}finally{e.disabled=false;}});
}
async function render(){close();let p=location.pathname.replace(/\/$/,'')||'/';document.title='Make';const legalKey=p.replace(/^\/en\//,'/').slice(1);if(legalPages[legalKey])return legalPage(legalKey);if(p==='/help'||p.startsWith('/help/'))return publicHelpPage(p.split('/')[2]);if(!user){if(!['/','/login','/register','/resend-verification','/forgot-password','/verify','/reset-password'].includes(p)&&!p.startsWith('/en/'))history.replaceState({},'','/login?next='+encodeURIComponent(p+location.search));const mode=p.includes('resend-verification')?'resend':p.includes('register')?'register':p.includes('forgot')||p.includes('lost-password')?'forgot':p.includes('reset')?'reset':p==='/verify'?'verify':'login';return authPage(mode);}if(['/login','/register','/resend-verification','/forgot-password','/verify','/reset-password'].includes(p)){history.replaceState({},'','/organization/1/dashboard');return dashboard();}if(p==='/profile')return profilePage();if(p==='/help'||p.startsWith('/help/'))return helpPage(p.split('/')[2]);if(p==='/'||p==='/login'||p.endsWith('/dashboard')||/^\/organization\/\d+$/.test(p)||/^\/\d+$/.test(p))return dashboard();let m=p.match(/^\/\d+\/scenarios\/(add|[\w-]+)(?:\/edit)?$/);if(m)return editor(m[1]);if(/\/\d+\/scenarios$/.test(p))return scenarioList();if(p==='/templates')return templatePage();if(p.startsWith('/templates/'))return templatePage(p.split('/').pop());if(/\/user-roles\/organization\/\d+$/.test(p))return rolePage(p.split('/').pop());if(p.endsWith('/user-roles/organization'))return organization('user-roles');if(p.includes('/organization/'))return organization(p.split('/').pop());if(/^\/\d+\/(hooks|agent-profiles)\/[\w-]+$/.test(p))return integrationPage(p.split('/').pop());if(/^\/\d+\/data-stores\/[\w-]+$/.test(p))return storePage(p.split('/').pop());let kind=p.split('/').pop();if(['data-stores','devices','udts','hooks','keys','connections','agent-profiles','apps'].includes(kind))return resourcePage(kind);if(p==='/notifications')return shell('<h1>Notifications</h1><section class="notification-empty">There are no notifications in this zone.</section>','notifications','notifications-page');
 if(kind==='agents'||kind==='scenario-agents')return shell(`<h1>AI Agents <span class="badge">New</span></h1><section class="empty"><h2>Build workflows that think and adapt</h2><p>Make AI Agents turn complex inputs into smart decisions and actions, all on one canvas.</p><a class="primary" style="padding:10px;border-radius:6px" href="/1/scenarios/add">Create agentic scenario</a></section>`,'agents');
 if(kind==='knowledge')return shell('<h1>Knowledge files</h1><section class="empty">No knowledge files</section>','agents');
 if(kind==='credentials-requests')return shell('<h1>Credential requests</h1><div class="tabs"><a class="active">Received</a></div><section class="empty"><h3>No requests received</h3><p>Credential requests sent to you will appear here.</p></section>','credentials');
 if(p==='/1/templates')return shell('<h1>Team templates</h1><section class="empty"><h2>Templates for your team to share</h2><p>Team templates are a special feature of the Teams plan, letting you create and share templates exclusively with your team.</p><a href="/organization/1/subscription">Upgrade to Teams</a></section>','templates');
 if(p==='/1/templates/add')return editor('add');if(kind==='team')return settingsModalPage();
 shell('<h1>Page not implemented yet</h1><p>This route remains in the implementation backlog.</p><a href="/organization/1/dashboard">Back to Dashboard</a>');}
function settingsModalPage(){
 shell(`<h1>Team settings</h1><form id="settings-form" class="panel config-form team-settings-form"><label for="settings-organization">Organization name</label><input id="settings-organization" name="organization" value="${esc(settings.organization)}" required maxlength="160"><label for="settings-team">Team name</label><input id="settings-team" name="team" value="${esc(settings.team)}" required maxlength="160"><label for="settings-timezone">Time zone</label><select id="settings-timezone" name="timezone">${['America/Toronto','UTC','Europe/London','Asia/Shanghai'].map(t=>`<option ${settings.timezone===t?'selected':''}>${t}</option>`).join('')}</select><div id="settings-result" role="status"></div><div class="form-actions"><button class="primary">Save</button></div></form>`,'','team-settings-page');
 $('#settings-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('#settings-result').textContent='';try{settings=await api('/settings','PUT',Object.fromEntries(new FormData(e.target)));await render();toast('Settings saved');}catch(err){$('#settings-result').innerHTML=`<p class="error">${esc(err.message)}</p>`;}finally{button.disabled=false;}};
}
async function action(name,el){switch(name){
 case 'close':close();break;
 case 'dismiss-banner':el.closest('.banner').remove();break;
 case 'account':modal('Your account',`<p><strong>${esc(user.display_name)}</strong><br>${esc(user.email_normalized)}</p><p><a href="/profile">Profile</a></p><a href="/1/team">Organization and team settings</a><div class="form-actions"><button data-action="logout">Sign out</button></div>`);break;
 case 'logout':await api('/auth/logout','POST',{});user=null;await api('/session');go('/login');break;
 case 'switch-org':modal('My Organization',`<a href="/organization/1/dashboard">${esc(settings.organization)}</a><div class="panel"><a href="/1/team">${esc(settings.team)} &nbsp; →</a></div>`);break;
 case 'search':modal('Search',`<input id="global-query" placeholder="Search scenarios and pages" style="width:100%"><div class="search-results" id="search-results"></div>`);{const rows=await api('/scenarios');function show(){const q=$('#global-query').value.toLowerCase();$('#search-results').innerHTML=[...navs.map(([n,p])=>({name:n,path:p})),...rows.map(r=>({name:r.name,path:'/1/scenarios/'+r.id+'/edit'}))].filter(x=>x.name.toLowerCase().includes(q)).map(x=>`<a href="${x.path}">${esc(x.name)}</a>`).join('')||'<p class="muted">No results found</p>';}show();$('#global-query').oninput=show;$('#global-query').focus();}break;
 case 'help':modal('Help',`<h3>Build your first scenario</h3><p>Add a module, configure its fields, then select Save. Run once executes the scenario and shows each module’s input and output.</p><p>Use <code>{{variableName}}</code> to pass values between modules. Your scenario history remains available after you sign in again.</p><p><a href="/help">Help center</a></p><a href="/templates">Explore templates</a>`);break;
 case 'mcp':go('/1/agent-profiles');break;
 case 'maia-start':go('/1/scenarios/add?maia=1');break;
 case 'maia-generate':modal('Build with Maia','<p>AI generation is not connected in this local version. You can build a scenario using the module picker.</p><div class="form-actions"><button class="primary" data-action="picker">Add a module</button></div>');break;
 case 'inspiration':modal('Get inspiration','<p>Create a variable, transform text, or parse JSON.</p><button class="primary" data-action="picker">Explore modules</button>');break;
 case 'close-maia':maia=false;drawEditor();break;
 case 'toggle-maia':maia=!maia;drawEditor();break;
 case 'picker':close();await picker();break;
 case 'close-picker':$('#picker').innerHTML='';break;
 case 'add-module':snapshot();{const id=crypto.randomUUID();scenario.graph.push({id,type:el.dataset.type,config:el.dataset.type==='json-parse'?{array_mode:'split'}:{}});drawEditor();await configure(id);}break;
 case 'configure':await configure(el.dataset.id);break;
 case 'insert-filter':{snapshot();const id=crypto.randomUUID();scenario.graph.splice(Number(el.dataset.index),0,{id,type:'filter',config:{}});drawEditor();configureFilter(id);}break;
 case 'setup-webhook':{const module=scenario.graph.find(m=>m.id===el.dataset.id);snapshot();module.config=Object.fromEntries(new FormData($('#module-form')));scenario.interval_minutes=0;await saveScenario();close();go('/1/hooks?scenario='+scenario.id);}break;
 case 'delete-module':snapshot();scenario.graph=scenario.graph.filter(x=>x.id!==el.dataset.id);close();drawEditor();break;
 case 'undo':if(undo.length){redo.push(editorState());Object.assign(scenario,JSON.parse(undo.pop()));dirty=true;drawEditor();}break;
 case 'redo':if(redo.length){undo.push(editorState());Object.assign(scenario,JSON.parse(redo.pop()));dirty=true;drawEditor();}break;
 case 'save':await saveScenario();toast('Scenario saved');break;
 case 'run':el.disabled=true;try{await saveScenario();showRun(await api('/scenarios/'+scenario.id+'/run','POST',{}));}finally{el.disabled=false;}break;
 case 'history':await historyModal(el.dataset.id);break;
 case 'schedule':scheduleDialog();break;
 case 'activate':scenario.active=!scenario.active;try{await saveScenario();toast(scenario.active?(scenario.interval_minutes===0?'Scenario activated for on-demand runs.':'Scenario activated. Next run in '+scenario.interval_minutes+' minutes.'):'Scenario deactivated');}catch(err){scenario.active=!scenario.active;throw err;}break;
 case 'scenario-settings':await scenarioSettings();break;
 case 'editor-menu':modal('Scenario options','<button data-action="blueprint">Export blueprint</button> <button data-action="import-blueprint">Import blueprint</button>');break;
 case 'blueprint':{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({name:scenario.name,graph:scenario.graph},null,2)],{type:'application/json'}));a.href=url;a.download='scenario-blueprint.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}break;
 case 'import-blueprint':importBlueprintDialog();break;
 case 'scenario-menu':modal('Scenario options',`<button data-action="scenario-clone" data-id="${el.dataset.id}">Clone</button> <button data-action="scenario-trash" data-id="${el.dataset.id}">${location.search.includes('trash')?'Restore':'Move to trash'}</button>`);break;
 case 'scenario-clone':await api('/scenarios/'+el.dataset.id+'/clone','POST',{});close();await render();toast('Scenario cloned');break;
 case 'scenario-trash':await api('/scenarios/'+el.dataset.id+(location.search.includes('trash')?'/restore':'/trash'),'POST',{});close();await render();break;
 case 'add-folder':await resourceAdd('folders');break;
 case 'add-label':await resourceAdd('labels');break;
 case 'resource-add':await resourceAdd(el.dataset.kind);break;
 case 'resource-delete':if(confirm('Delete this item?')){await api('/resources/'+el.dataset.kind+'/'+el.dataset.id,'DELETE');await render();}break;
 case 'manage-classification':await manageClassification(el.dataset.kind,el.dataset.id);break;
 case 'resource-view':if(['hooks','agent-profiles'].includes(el.dataset.kind)){go('/1/'+el.dataset.kind+'/'+el.dataset.id);break;}if(el.dataset.kind==='data-stores'){go('/1/data-stores/'+el.dataset.id);break;}{const rows=await api('/resources/'+el.dataset.kind);const r=rows.find(x=>x.id===el.dataset.id);modal(r.name,`<pre style="white-space:pre-wrap">${esc(JSON.stringify(r.config,null,2))}</pre>`);}break;
 case 'role':go('/organization/1/user-roles/organization/'+(11+['Owner','Admin','Member','Accountant','App Developer','Guest'].indexOf(el.dataset.name)));break;
 case 'plan':modal('Get '+el.dataset.name,'<p>Local subscription checkout has not been implemented yet.</p>');break;
 case 'provider':providerFlow(el.dataset.provider);break;
 case 'other-login':modal('Other sign-in options','<button class="social" data-action="provider" data-provider="Microsoft">Continue with Microsoft</button> <button class="social" data-action="provider" data-provider="Apple">Continue with Apple</button>');break;
 case 'template-use':{const t=templates.find(t=>t.path.split('/').pop()===el.dataset.id);const s=await api('/scenarios','POST',{name:t.title,graph:t.modules.map(type=>({id:crypto.randomUUID(),type,config:{}}))});go('/1/scenarios/'+s.id+'/edit');}break;
 }}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();try{await action(el.dataset.action,el);}catch(err){toast(err.message);}return;}const a=e.target.closest('a[href]');if(a&&a.origin===location.origin&&!a.download&&!e.ctrlKey&&!e.metaKey){e.preventDefault();go(a.pathname+a.search+a.hash);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();if($('#picker'))$('#picker').innerHTML='';}if((e.ctrlKey||e.metaKey)&&e.key==='k'&&user){e.preventDefault();action('search',{}).catch(err=>toast(err.message));}if((e.ctrlKey||e.metaKey)&&e.key==='s'&&scenario&&$('.editor')){e.preventDefault();saveScenario().then(()=>toast('Scenario saved')).catch(err=>toast(err.message));}});
window.addEventListener('pageshow',async e=>{if(e.persisted){const s=await api('/session');user=s.account;await render();}});
window.addEventListener('popstate',()=>{dirty=false;render().catch(e=>toast(e.message));});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
(async()=>{try{[assets,templates,countries]=await Promise.all([fetch('/static/asset-map.json').then(r=>r.json()),fetch('/static/templates.json').then(r=>r.json()),fetch('/static/countries.json').then(r=>r.json())]);const s=await api('/session');user=s.account;if(user)settings=await api('/settings');await render();}catch(err){$('#app').innerHTML=`<div class="panel"><h1>Make could not load</h1><p>${esc(err.message)}</p><button data-action="reload">Reload</button></div>`;}})();

async function rolePage(id){
 const roles=await fetch('/static/roles.json').then(r=>r.json()),role=roles[id];if(!role)return organization('user-roles');
 const groups=role.permissions.reduce((out,p)=>{(out[p.group]??=[]).push(p);return out;},{});
 shell(`<nav class="role-breadcrumb" aria-label="Breadcrumb"><a href="/organization/1/user-roles">User roles</a><span>›</span><a href="/organization/1/user-roles/organization">Organization roles</a><span>›</span><span>${esc(role.name)}</span></nav><h1>${esc(role.name)} <span class="pill">Default</span></h1><p class="role-description">${esc(role.description)}</p><h2 class="permissions-heading">Permissions <span class="pill">${role.permissions.filter(p=>p.enabled).length}/${role.permissions.length} enabled</span></h2><div class="permission-groups">${Object.entries(groups).map(([name,rows])=>`<details class="permission-group" open><summary><strong>${esc(name)}</strong><span class="pill">${rows.filter(p=>p.enabled).length}/${rows.length} enabled</span></summary><div>${rows.map(p=>`<div class="permission-row"><div class="permission-copy"><strong>${esc(p.name)}</strong><p>${esc(p.description)}</p></div><div class="permission-state"><span class="permission-requires">${p.requires.length?'Requires ':''}${p.requires.map(x=>`<span class="pill">${esc(x)}</span>`).join(' ')}</span><input class="notification-check permission-switch" type="checkbox" aria-label="${esc(p.name)}" ${p.enabled?'checked':''} disabled></div></div>`).join('')}</div></details>`).join('')}</div>`,'org','role-detail-page');
}

async function storePage(id){const store=await api('/stores/'+id);shell(`<p><a href="/1/data-stores">Data stores</a> / ${esc(store.name)}</p><div class="flex between"><h1>${esc(store.name)}</h1><button class="primary" id="add-record">Add record</button></div><div class="list-toolbar"><input id="record-search" placeholder="Search records" aria-label="Search records"></div><table class="table"><thead><tr><th>Key</th><th>Data</th><th>Updated</th><th></th></tr></thead><tbody id="record-rows"></tbody></table>`);function show(){const q=$('#record-search').value.toLowerCase();$('#record-rows').innerHTML=store.records.filter(r=>(r.key+' '+JSON.stringify(r.value)).toLowerCase().includes(q)).map(r=>`<tr><td>${esc(r.key)}</td><td><code>${esc(JSON.stringify(r.value))}</code></td><td>${new Date(r.updated*1000).toLocaleString()}</td><td><button data-record-edit="${esc(r.key)}">Edit</button> <button data-record-delete="${esc(r.key)}">Delete</button></td></tr>`).join('')||'<tr><td colspan="4">No records found</td></tr>';$$('[data-record-edit]').forEach(el=>el.onclick=()=>edit(store.records.find(r=>r.key===el.dataset.recordEdit)));$$('[data-record-delete]').forEach(el=>el.onclick=async()=>{if(confirm('Delete this record?')){try{await api('/stores/'+id+'/records/'+encodeURIComponent(el.dataset.recordDelete),'DELETE');await storePage(id);}catch(e){toast(e.message);}}});}function edit(record){modal(record?'Edit record':'Add record',`<form id="record-form" class="config-form"><label for="record-key">Key*</label><input id="record-key" name="key" value="${esc(record?.key||'')}" ${record?'readonly':''} required><label for="record-value">Record data</label><textarea id="record-value" name="value">${esc(JSON.stringify(record?.value||{},null,2))}</textarea><div class="form-actions"><button type="button" data-action="close">Close</button><button class="primary">Save</button></div></form>`);$('#record-form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);await api('/stores/'+id+'/records/'+encodeURIComponent(f.get('key')),'PUT',{value:JSON.parse(f.get('value'))});close();await storePage(id);toast('Record saved');}catch(e){toast(e.message);}};}show();$('#record-search').oninput=show;$('#add-record').onclick=()=>edit(null);}

function providerFlow(provider,verify=false){modal('Continue with '+provider,`<p class="muted">Local sign-in adapter: verify your email to continue. This does not connect to a real ${esc(provider)} account.</p><form id="provider-form" class="config-form">${verify?'<label for="provider-code">Verification code</label><input id="provider-code" name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required>':'<label for="provider-email">Email</label><input id="provider-email" name="email" type="email" required>'}<div id="provider-error"></div><div class="form-actions"><button type="button" data-action="close">Cancel</button><button class="primary">${verify?'Verify and continue':'Continue'}</button></div></form>`);$('#provider-form').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));await api('/auth/provider-'+(verify?'verify':'start'),'POST',{...d,provider});if(!verify)return providerFlow(provider,true);const session=await api('/session');user=session.account;settings=await api('/settings');close();go('/organization/1/dashboard');}catch(err){$('#provider-error').innerHTML=`<p class="error">${esc(err.message)}</p>`;}};}
